per_case_results.actual_sql:
SELECT "p6"."jumping_score" - "p23"."jumping_score" AS "score_difference"
FROM "players" "p6", "players" "p23"
WHERE "p6"."player_id" = 6 AND "p23"."player_id" = 23;

SELECT 100.0 * COUNT(*) FILTER (WHERE "height" < 180) FILTER (WHERE "overall_strength" > 70) / COUNT(*) AS "percentage"
FROM "players"
WHERE "overall_strength" > 70;
